// Content with portions generated by generative AI platform
package org.eclipse.kura.openapi;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Set;

import org.eclipse.kura.configuration.metatype.AD;
import org.eclipse.kura.configuration.metatype.OCD;
import org.eclipse.kura.configuration.metatype.Option;
import org.eclipse.kura.configuration.metatype.Scalar;
import org.eclipse.kura.rest.configuration.api.OcdDTO;
import org.junit.Test;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.google.gson.Gson;
import com.networknt.schema.ValidationMessage;

import io.swagger.v3.core.util.Json31;

public class MetatypeOptionsSchemaTest {

    private JsonNode document;
    private JsonNode payload;
    private Set<ValidationMessage> errors;

    @Test
    public void enumeratedOptionsMatchTheirConcreteSchema() throws Exception {
        givenDefinitionWithOptions();

        whenDefinitionIsValidated();

        thenDefinitionIsValid();
        thenOptionFieldsAreDocumented();
    }

    @Test
    public void numericOptionLabelIsRejected() throws Exception {
        givenDefinitionWithOptions();
        givenNumericOptionField("label");

        whenDefinitionIsValidated();

        thenDefinitionIsRejected();
    }

    @Test
    public void numericOptionValueIsRejected() throws Exception {
        givenDefinitionWithOptions();
        givenNumericOptionField("value");

        whenDefinitionIsValidated();

        thenDefinitionIsRejected();
    }

    private void givenDefinitionWithOptions() throws Exception {
        this.document = Json31.mapper().readTree(Files.readString(
                Path.of(System.getProperty("openapi.directory"), "openapi.json")));
        final Option option = mock(Option.class);
        when(option.getLabel()).thenReturn("Automatic");
        when(option.getValue()).thenReturn("auto");
        final AD attribute = mock(AD.class);
        when(attribute.getId()).thenReturn("mode");
        when(attribute.getType()).thenReturn(Scalar.STRING);
        when(attribute.getOption()).thenReturn(List.of(option));
        final OCD definition = mock(OCD.class);
        when(definition.getId()).thenReturn("test.component");
        when(definition.getAD()).thenReturn(List.of(attribute));
        this.payload = Json31.mapper().readTree(new Gson().toJson(new OcdDTO(definition)));
    }

    private void givenNumericOptionField(String field) {
        ((ObjectNode) this.payload.at("/ad/0/option/0")).put(field, 42);
    }

    private void whenDefinitionIsValidated() {
        this.errors = OpenApiSchemaValidator.payloadSchema(this.document, "OcdDTO")
                .validate(this.payload);
    }

    private void thenDefinitionIsValid() {
        assertTrue(this.errors.toString(), this.errors.isEmpty());
        assertEquals("Automatic", this.payload.at("/ad/0/option/0/label").asText());
        assertEquals("auto", this.payload.at("/ad/0/option/0/value").asText());
    }

    private void thenOptionFieldsAreDocumented() {
        assertEquals("#/components/schemas/OptionDTO",
                this.document.at("/components/schemas/AdDTO/properties/option/items/$ref").asText());
        assertEquals("string", this.document.at("/components/schemas/OptionDTO/properties/label/type").asText());
        assertEquals("string", this.document.at("/components/schemas/OptionDTO/properties/value/type").asText());
    }

    private void thenDefinitionIsRejected() {
        assertFalse(this.errors.isEmpty());
    }
}
